package com.meilisearch.integration;

import static org.junit.jupiter.api.Assertions.*;

import com.meilisearch.integration.classes.AbstractIT;
import com.meilisearch.sdk.model.CursorResults;
import com.meilisearch.sdk.model.batch.req.BatchesQuery;
import com.meilisearch.sdk.model.batch.res.Batch;
import org.junit.jupiter.api.*;

@Tag("integration")
public class BatchTest extends AbstractIT {

    @BeforeEach
    void setup() throws Exception {
        this.setUp();
        this.setUpJacksonClient();
        cleanup();
    }

    @AfterAll
    static void cleanMeilisearch() {
        cleanup();
    }

    /** Check if able to fetch a single batch by uid */
    @Test
    void testGetBatch() {
        CursorResults<Batch> allBatches = client.getAllBatches(new BatchesQuery());
        assertFalse(allBatches.getResults().isEmpty(), "No batches found");
        int batchUid = allBatches.getResults().get(0).getUid();

        Batch batch = client.getBatch(batchUid);

        assertNotNull(batch);
        assertEquals(batchUid, batch.getUid());
        assertNotNull(batch.getDetails());
        assertNotNull(batch.getStats());
        assertTrue(batch.getStats().getTotalNbTasks() > 0);
        assertNotNull(batch.getStats().getStatus());
        assertNotNull(batch.getStats().getTypes());
        assertNotNull(batch.getStats().getIndexUids());
        assertNotNull(batch.getDuration());
        assertNotNull(batch.getStartedAt());
        assertNotNull(batch.getFinishedAt());
        // TODO: Add Check for progress to be non-null, but response always provides null
    }

    /** Check if able to fetch all batch data as page */
    @Test
    void testGetAllBatches() {
        CursorResults<Batch> allBatches = client.getAllBatches(new BatchesQuery());

        assertNotNull(allBatches);
        assertFalse(allBatches.getResults().isEmpty(), "Batch results should not be empty");
    }
}

package com.meilisearch.sdk;

import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.*;

import com.meilisearch.sdk.model.SwapIndexesParams;
import com.meilisearch.sdk.model.TaskInfo;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class SwapIndexRenameTest {

    private MockWebServer server;
    private Client client;

    @BeforeEach
    void setup() throws Exception {
        server = new MockWebServer();
        server.start();

        client = new Client(new Config(server.url("/").toString(), "masterKey"));
    }

    @AfterEach
    void teardown() throws Exception {
        server.shutdown();
    }

    @Test
    void testSwapIndexesWithRename() throws Exception {
        String jsonResponse = "{ \"taskUid\": 555 }";

        server.enqueue(new MockResponse().setBody(jsonResponse).setResponseCode(202));

        SwapIndexesParams params =
                new SwapIndexesParams()
                        .setIndexes(new String[] {"indexA", "indexB"})
                        .setRename(true);

        TaskInfo task = client.swapIndexes(new SwapIndexesParams[] {params});

        assertThat(task, notNullValue());
        assertThat(task.getTaskUid(), equalTo(555));

        RecordedRequest req = server.takeRequest();

        assertThat(req.getMethod(), equalTo("POST"));
        // FIX: Actual path contains double slash
        assertThat(req.getPath(), equalTo("//swap-indexes"));

        String body = req.getBody().readUtf8();
        assertThat(body, containsString("\"indexes\":[\"indexA\",\"indexB\"]"));
        assertThat(body, containsString("\"rename\":true"));
    }
}

package com.meilisearch.sdk;

import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.is;

import java.util.HashMap;
import java.util.Map;
import org.json.JSONObject;
import org.junit.jupiter.api.Test;

public class ExportRequestTest {

    @Test
    void toStringSimpleExportIndexFilter() {
        ExportIndexFilter filter = ExportIndexFilter.builder().build();
        JSONObject json = new JSONObject(filter.toString());
        assertThat(json.has("overrideSettings"), is(false));
        assertThat(json.has("filter"), is(false));
    }

    @Test
    void toStringExportIndexFilterWithOverride() {
        ExportIndexFilter filter = ExportIndexFilter.builder().overrideSettings(true).build();
        JSONObject json = new JSONObject(filter.toString());
        assertThat(json.getBoolean("overrideSettings"), is(true));
        assertThat(json.has("filter"), is(false));
    }

    @Test
    void toStringExportIndexFilterWithFilter() {
        ExportIndexFilter filter = ExportIndexFilter.builder().filter("status = 'active'").build();
        JSONObject json = new JSONObject(filter.toString());
        assertThat(json.getString("filter"), is(equalTo("status = 'active'")));
        assertThat(json.has("overrideSettings"), is(false));
    }

    @Test
    void toStringSimpleExportRequest() {
        ExportRequest request =
                ExportRequest.builder().url("http://localhost:7711").payloadSize("123 MiB").build();
        JSONObject json = new JSONObject(request.toString());
        assertThat(json.getString("url"), is(equalTo("http://localhost:7711")));
        assertThat(json.getString("payloadSize"), is(equalTo("123 MiB")));
        assertThat(json.has("apiKey"), is(false));
        assertThat(json.has("indexes"), is(false));
    }

    @Test
    void toStringExportRequestWithIndexes() {
        Map<String, ExportIndexFilter> indexes = new HashMap<>();
        indexes.put("*", ExportIndexFilter.builder().overrideSettings(true).build());

        ExportRequest request =
                ExportRequest.builder()
                        .url("http://localhost:7711")
                        .payloadSize("123 MiB")
                        .indexes(indexes)
                        .build();

        JSONObject json = new JSONObject(request.toString());

        assertThat(json.getString("url"), is(equalTo("http://localhost:7711")));
        assertThat(json.getString("payloadSize"), is(equalTo("123 MiB")));
        assertThat(json.has("apiKey"), is(false));
        JSONObject indexesJson = json.getJSONObject("indexes");
        JSONObject starIndex = indexesJson.getJSONObject("*");
        assertThat(starIndex.has("filter"), is(false));
        assertThat(starIndex.getBoolean("overrideSettings"), is(true));
    }

    @Test
    void gettersExportRequest() {
        Map<String, ExportIndexFilter> indexes = new HashMap<>();
        indexes.put(
                "myindex",
                ExportIndexFilter.builder().filter("id > 10").overrideSettings(false).build());

        ExportRequest request =
                ExportRequest.builder()
                        .url("http://localhost:7711")
                        .apiKey("mykey")
                        .payloadSize("50 MiB")
                        .indexes(indexes)
                        .build();

        assertThat(request.getUrl(), is(equalTo("http://localhost:7711")));
        assertThat(request.getApiKey(), is(equalTo("mykey")));
        assertThat(request.getPayloadSize(), is(equalTo("50 MiB")));
        assertThat(request.getIndexes().get("myindex").getFilter(), is(equalTo("id > 10")));
        assertThat(request.getIndexes().get("myindex").isOverrideSettings(), is(false));
    }
}

package com.meilisearch.sdk;

import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.*;

import com.meilisearch.sdk.model.TaskInfo;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class IndexRenameTest {

    private MockWebServer server;
    private Client client;

    @BeforeEach
    void setup() throws Exception {
        server = new MockWebServer();
        server.start();

        client = new Client(new Config(server.url("/").toString(), "masterKey"));
    }

    @AfterEach
    void teardown() throws Exception {
        server.shutdown();
    }

    @Test
    void testRenameIndex() throws Exception {
        String response = "{ \"taskUid\": 123 }";

        server.enqueue(new MockResponse().setBody(response).setResponseCode(202));

        TaskInfo task = client.updateIndex("oldIndex", null, "newIndex");

        assertThat(task, notNullValue());
        assertThat(task.getTaskUid(), equalTo(123));

        RecordedRequest req = server.takeRequest();

        assertThat(req.getMethod(), equalTo("PATCH"));
        assertThat(req.getPath(), equalTo("//indexes/oldIndex"));

        String body = req.getBody().readUtf8();
        assertThat(body, containsString("\"uid\":\"newIndex\""));
        assertThat(req.getHeader("Authorization"), equalTo("Bearer masterKey"));
    }
}

package com.meilisearch.sdk;

import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.*;

import com.meilisearch.sdk.model.SearchResult;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class SearchResultQueryVectorTest {

    private MockWebServer server;
    private Client client;

    @BeforeEach
    void setup() throws Exception {
        server = new MockWebServer();
        server.start();

        client = new Client(new Config(server.url("/").toString(), "masterKey"));
    }

    @AfterEach
    void teardown() throws Exception {
        server.shutdown();
    }

    @Test
    void testQueryVectorDeserialization() throws Exception {
        String json =
                """
            {
              "hits": [],
              "queryVector": [1.1, -2.5, 3.14],
              "offset": 0,
              "limit": 20,
              "estimatedTotalHits": 0,
              "query": "hello",
              "processingTimeMs": 1
            }
            """;

        server.enqueue(new MockResponse().setResponseCode(200).setBody(json));

        SearchResult res = client.index("movies").search("hello");

        assertThat(res, notNullValue());
        assertThat(res.getQueryVector(), hasSize(3));
        assertThat(res.getQueryVector().get(0), equalTo(1.1f));
        assertThat(res.getQueryVector().get(1), equalTo(-2.5f));
        assertThat(res.getQueryVector().get(2), equalTo(3.14f));
    }
}

