package com.meilisearch.sdk;

import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.*;
import static org.hamcrest.Matchers.equalTo;

import com.meilisearch.integration.classes.AbstractIT;
import com.meilisearch.integration.classes.TestData;
import com.meilisearch.sdk.model.Settings;
import com.meilisearch.sdk.model.TaskInfo;
import com.meilisearch.sdk.utils.Movie;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

class SettingsHandlerTest extends AbstractIT {

    private TestData<Movie> testData;

    @BeforeEach
    public void initialize() {
        setUp();
        setUpJacksonClient();
        if (testData == null) testData = this.getTestData(MOVIES_INDEX, Movie.class);
        cleanup();
    }

    @AfterAll
    static void cleanMeilisearch() {
        cleanup();
    }

    /** Tests of the dictionary setting methods */
    @Test
    @DisplayName("Test get dictionary settings by uid")
    public void testGetDictionarySettings() throws Exception {
        Index index = createIndex("testGetDictionarySettings");
        Settings initialSettings = index.getSettings();
        String[] initialDictionary = index.getDictionarySettings();

        assertThat(initialDictionary, is(arrayWithSize(initialSettings.getDictionary().length)));
        assertThat(initialDictionary, is(equalTo(initialSettings.getDictionary())));
    }

    @Test
    @DisplayName("Test update dictionary settings")
    public void testUpdateDictionarySettings() throws Exception {
        Index index = createIndex("testUpdateDictionarySettings");
        String[] initialDictionary = index.getDictionarySettings();
        String[] newDictionary = {"J. R. R.", "W. E. B."};

        index.waitForTask(index.updateDictionarySettings(newDictionary).getTaskUid());
        String[] updatedDictionarySettings = index.getDictionarySettings();

        assertThat(updatedDictionarySettings, is(arrayWithSize(newDictionary.length)));
        assertThat(updatedDictionarySettings, is(equalTo(newDictionary)));
        assertThat(updatedDictionarySettings, is(not(arrayWithSize(initialDictionary.length))));
    }

    @Test
    @DisplayName("Test reset dictionary settings")
    public void testResetDictionarySettings() throws Exception {
        Index index = createIndex("testResetDictionarySettings");
        String[] initialDictionary = index.getDictionarySettings();
        String[] newDictionary = {"J. R. R.", "W. E. B."};

        index.waitForTask(index.updateDictionarySettings(newDictionary).getTaskUid());
        String[] updatedDictionarySettings = index.getDictionarySettings();

        index.waitForTask(index.resetDictionarySettings().getTaskUid());
        String[] dictionaryAfterReset = index.getDictionarySettings();

        assertThat(updatedDictionarySettings, is(arrayWithSize(newDictionary.length)));
        assertThat(updatedDictionarySettings, is(equalTo(newDictionary)));
        assertThat(updatedDictionarySettings, is(not(arrayWithSize(initialDictionary.length))));
        assertThat(dictionaryAfterReset, is(not(arrayWithSize(updatedDictionarySettings.length))));
        assertThat(dictionaryAfterReset, is(arrayWithSize(initialDictionary.length)));
        assertThat(dictionaryAfterReset, is(equalTo(initialDictionary)));
    }

    private Index createIndex(String indexUid) throws Exception {
        Index index = client.index(indexUid);
        TaskInfo updateInfo = index.addDocuments(testData.getRaw());
        index.waitForTask(updateInfo.getTaskUid());

        return index;
    }
}

package com.meilisearch.sdk;

import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.is;

import com.meilisearch.sdk.model.TasksQuery;
import org.junit.jupiter.api.Test;

class TaskHandlerUtilsTest {

    @Test
    void addIndexUidToQueryWithParamNull() {
        final Config config = new Config("http://localhost:7700", "masterKey");
        TasksHandler classToTest = new TasksHandler(config);
        TasksQuery param = null;
        TasksQuery query = classToTest.addIndexUidToQuery("indexName", param);

        assertThat(query.toQuery(), is(equalTo("?indexUids=indexName")));
    }

    @Test
    void addIndexUidToQueryWithParam() {
        final Config config = new Config("http://localhost:7700", "masterKey");
        TasksHandler classToTest = new TasksHandler(config);
        TasksQuery param = new TasksQuery().setIndexUids(new String[] {});
        TasksQuery query = classToTest.addIndexUidToQuery("indexName", param);

        assertThat(query.toQuery(), is(equalTo("?indexUids=indexName")));
    }

    @Test
    void addIndexUidToQueryWithOneIndexUid() {
        final Config config = new Config("http://localhost:7700", "masterKey");
        TasksHandler classToTest = new TasksHandler(config);
        TasksQuery param = new TasksQuery().setIndexUids(new String[] {"indexName2"});
        TasksQuery query = classToTest.addIndexUidToQuery("indexName1", param);

        assertThat(query.toQuery(), is(equalTo("?indexUids=indexName2,indexName1")));
    }

    @Test
    void addIndexUidToQueryWithMultipleIndexUids() {
        final Config config = new Config("http://localhost:7700", "masterKey");
        TasksHandler classToTest = new TasksHandler(config);
        TasksQuery param =
                new TasksQuery()
                        .setIndexUids(
                                new String[] {
                                    "indexName2", "indexName3", "indexName4", "indexName5"
                                });
        TasksQuery query = classToTest.addIndexUidToQuery("indexName1", param);

        assertThat(
                query.toQuery(),
                is(equalTo("?indexUids=indexName2,indexName3,indexName4,indexName5,indexName1")));
    }
}

package com.meilisearch.integration;

import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.is;
import static org.junit.jupiter.api.Assertions.assertThrows;

import com.meilisearch.integration.classes.AbstractIT;
import com.meilisearch.sdk.Client;
import com.meilisearch.sdk.Config;
import com.meilisearch.sdk.exceptions.APIError;
import com.meilisearch.sdk.exceptions.MeilisearchApiException;
import com.meilisearch.sdk.exceptions.MeilisearchCommunicationException;
import com.meilisearch.sdk.model.TaskError;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

@Tag("integration")
public class ExceptionsTest extends AbstractIT {

    @BeforeEach
    public void initialize() {
        this.setUp();
    }

    @AfterAll
    static void cleanMeilisearch() {
        cleanup();
    }

    @Test
    public void testMeilisearchCommunicationException() throws Exception {
        String indexUid = "MeilisearchCommunicationException";
        Client wrongClient = new Client(new Config("http://wrongurl:1234", "masterKey"));

        assertThrows(MeilisearchCommunicationException.class, () -> wrongClient.getIndex(indexUid));
    }

    /** Test MeilisearchApiException serialization and getters */
    @Test
    public void testErrorSerializeAndGetters() {
        String message = "You must have an authorization token";
        String code = "missing_authorization_header";
        String type = "authentication_error";
        String link =
                "https://www.meilisearch.com/docs/reference/errors/error_codes#missing_authorization_header";
        try {
            throw new MeilisearchApiException(new APIError(message, code, type, link));
        } catch (MeilisearchApiException e) {
            assertThat(e.getMessage(), is(equalTo(message)));
            assertThat(e.getCode(), is(equalTo(code)));
            assertThat(e.getType(), is(equalTo(type)));
            assertThat(e.getLink(), is(equalTo(link)));
        }
    }

    /** Test Task Error Getters */
    @Test
    public void testTaskErrorGetters() {
        TaskError error = new TaskError();
        error.setCode("wrong field");
        assertThat(error.getCode(), is(equalTo("wrong field")));
    }

    /** Test MeilisearchApiException is thrown on Meilisearch bad request */
    @Test
    public void testMeilisearchApiExceptionBadRequest() throws Exception {
        String indexUid = "MeilisearchApiExceptionBadRequest";
        assertThrows(MeilisearchApiException.class, () -> client.getIndex(indexUid));
        try {
            client.getIndex(indexUid);
        } catch (MeilisearchApiException e) {
            assertThat(e.getCode(), is(equalTo("index_not_found")));
        }
    }
}

package com.meilisearch.sdk;

import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.is;

import com.meilisearch.sdk.model.Hybrid;
import org.junit.jupiter.api.Test;

class IndexSearchRequestTest {
    @Test
    void toStringWithHybridUsingBuilder() {
        IndexSearchRequest classToTest =
                IndexSearchRequest.builder()
                        .q("This is a Test")
                        .hybrid(Hybrid.builder().semanticRatio(0.5).embedder("default").build())
                        .build();

        String expected =
                "{\"q\":\"This is a Test\",\"hybrid\":{\"semanticRatio\":0.5,\"embedder\":\"default\"}}";
        assertThat(classToTest.toString(), is(equalTo(expected)));

        // Verify getters
        assertThat(classToTest.getHybrid().getSemanticRatio(), is(equalTo(0.5)));
        assertThat(classToTest.getHybrid().getEmbedder(), is(equalTo("default")));
    }

    @Test
    void toStringWithHybridAndOtherParameters() {
        IndexSearchRequest classToTest =
                IndexSearchRequest.builder()
                        .q("This is a Test")
                        .offset(200)
                        .limit(900)
                        .hybrid(
                                Hybrid.builder()
                                        .semanticRatio(0.7)
                                        .embedder("custom-embedder")
                                        .build())
                        .build();

        String expected =
                "{\"q\":\"This is a Test\",\"hybrid\":{\"semanticRatio\":0.7,\"embedder\":\"custom-embedder\"},\"offset\":200,\"limit\":900}";
        assertThat(classToTest.toString(), is(equalTo(expected)));
    }

    @Test
    void toStringWithHybridOnlyEmbedder() {
        IndexSearchRequest classToTest =
                new IndexSearchRequest("someIndexUuid")
                        .setQuery("This is a Test")
                        .setHybrid(Hybrid.builder().embedder("default").build());

        String expected = "{\"q\":\"This is a Test\",\"hybrid\":{\"embedder\":\"default\"}}";
        assertThat(classToTest.toString(), is(equalTo(expected)));
    }
}

package com.meilisearch.sdk;

import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.is;

import org.json.JSONObject;
import org.junit.jupiter.api.Test;

class SimilarDocumentRequestTest {

    @Test
    void toStringDefaultValues() {
        SimilarDocumentRequest request = new SimilarDocumentRequest();
        JSONObject json = new JSONObject(request.toString());

        // only id and embedder should be absent (null) by default
        assertThat(json.has("id"), is(false));
        assertThat(json.has("embedder"), is(false));
        assertThat(json.has("attributesToRetrieve"), is(false));
        assertThat(json.has("offset"), is(false));
        assertThat(json.has("limit"), is(false));
        assertThat(json.has("filter"), is(false));
        assertThat(json.has("showRankingScore"), is(false));
        assertThat(json.has("showRankingScoreDetails"), is(false));
        assertThat(json.has("rankingScoreThreshold"), is(false));
        assertThat(json.has("retrieveVectors"), is(false));
    }

    @Test
    void toStringAllParameters() {
        SimilarDocumentRequest request =
                new SimilarDocumentRequest()
                        .setId("123")
                        .setEmbedder("custom")
                        .setAttributesToRetrieve(new String[] {"title", "description"})
                        .setOffset(10)
                        .setLimit(20)
                        .setFilter("genre = 'action'")
                        .setShowRankingScore(true)
                        .setShowRankingScoreDetails(true)
                        .setRankingScoreThreshold(0.5)
                        .setRetrieveVectors(true);

        JSONObject json = new JSONObject(request.toString());
        assertThat(json.getString("id"), is(equalTo("123")));
        assertThat(json.getString("embedder"), is(equalTo("custom")));
        assertThat(json.getJSONArray("attributesToRetrieve").getString(0), is(equalTo("title")));
        assertThat(
                json.getJSONArray("attributesToRetrieve").getString(1), is(equalTo("description")));
        assertThat(json.getInt("offset"), is(equalTo(10)));
        assertThat(json.getInt("limit"), is(equalTo(20)));
        assertThat(json.getString("filter"), is(equalTo("genre = 'action'")));
        assertThat(json.getBoolean("showRankingScore"), is(equalTo(true)));
        assertThat(json.getBoolean("showRankingScoreDetails"), is(equalTo(true)));
        assertThat(json.getDouble("rankingScoreThreshold"), is(equalTo(0.5)));
        assertThat(json.getBoolean("retrieveVectors"), is(equalTo(true)));
    }

    @Test
    void gettersAndSetters() {
        SimilarDocumentRequest request =
                SimilarDocumentRequest.builder()
                        .id("123")
                        .embedder("custom")
                        .attributesToRetrieve(new String[] {"title", "description"})
                        .offset(10)
                        .limit(20)
                        .filter("genre = 'action'")
                        .showRankingScore(true)
                        .showRankingScoreDetails(true)
                        .rankingScoreThreshold(0.5)
                        .retrieveVectors(true)
                        .build();

        assertThat(request.getId(), is(equalTo("123")));
        assertThat(request.getEmbedder(), is(equalTo("custom")));
        assertThat(
                request.getAttributesToRetrieve(),
                is(equalTo(new String[] {"title", "description"})));
        assertThat(request.getOffset(), is(equalTo(10)));
        assertThat(request.getLimit(), is(equalTo(20)));
        assertThat(request.getFilter(), is(equalTo("genre = 'action'")));
        assertThat(request.getShowRankingScore(), is(equalTo(true)));
        assertThat(request.getShowRankingScoreDetails(), is(equalTo(true)));
